require __DIR__.'/../app/bootstrap.php';require_permission('engagement.manage');$u=current_user();$msg=$err=null;$tab=in_array($_GET['tab']??'',['dashboard','popups','notifications'],true)?$_GET['tab']:'dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$action=(string)($_POST['action']??'');if($action==='save_popup'){$id=(int)($_POST['id']??0);$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('Popup title is required.');$aud=in_array($_POST['audience']??'all',['all','guests','users','role'],true)?$_POST['audience']:'all';$display=in_array($_POST['display_type']??'modal',['modal','banner','toast'],true)?$_POST['display_type']:'modal';$repeat=in_array($_POST['repeat_policy']??'once_session',['once_session','once_day','every_visit'],true)?$_POST['repeat_policy']:'once_session';$data=[$title,trim((string)$_POST['body'])?:null,trim((string)$_POST['image_url'])?:null,trim((string)$_POST['action_label'])?:null,engagement_safe_link((string)$_POST['action_url'])?:null,$display,$aud,trim((string)$_POST['target_role'])?:null,$repeat,trim((string)$_POST['starts_at'])?:null,trim((string)$_POST['ends_at'])?:null,isset($_POST['enabled'])?1:0,max(1,(int)($_POST['priority']??10)),(int)$u['id']];if($id)db()->prepare('UPDATE popup_campaigns SET title=?,body=?,image_url=?,action_label=?,action_url=?,display_type=?,audience=?,target_role=?,repeat_policy=?,starts_at=?,ends_at=?,enabled=?,priority=?,created_by=? WHERE id=?')->execute(array_merge($data,[$id]));else db()->prepare('INSERT INTO popup_campaigns(title,body,image_url,action_label,action_url,display_type,audience,target_role,repeat_policy,starts_at,ends_at,enabled,priority,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$msg='Popup campaign saved.';}elseif($action==='delete_popup'){db()->prepare('DELETE FROM popup_campaigns WHERE id=?')->execute([(int)$_POST['id']]);$msg='Popup deleted.';}elseif($action==='save_notification'){$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('Notification title is required.');$target=in_array($_POST['target_type']??'all',['all','user','role'],true)?$_POST['target_type']:'all';$role=trim((string)($_POST['target_role']??''));if($target==='role'&&!isset(core_role_registry()[$role]))throw new RuntimeException('Choose a valid role.');db()->prepare("INSERT INTO site_notifications(title,body,notification_type,target_type,target_user_id,target_role,action_url,icon,starts_at,expires_at,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$title,trim((string)$_POST['body'])?:null,in_array($_POST['notification_type']??'info',['info','success','warning','promotion'],true)?$_POST['notification_type']:'info',$target,(int)($_POST['target_user_id']??0)?:null,$role?:null,engagement_safe_link((string)$_POST['action_url'])?:null,trim((string)$_POST['icon'])?:'🔔',trim((string)$_POST['starts_at'])?:null,trim((string)$_POST['expires_at'])?:null,in_array($_POST['status']??'published',['draft','published','archived'],true)?$_POST['status']:'published',(int)$u['id']]);$msg='Notification published.';}elseif($action==='delete_notification'){db()->prepare('DELETE FROM site_notifications WHERE id=?')->execute([(int)$_POST['id']]);$msg='Notification deleted.';}}catch(Throwable $e){$err=$e->getMessage();}}
$editPopup=null;if(isset($_GET['edit_popup'])){$q=db()->prepare('SELECT * FROM popup_campaigns WHERE id=?');$q->execute([(int)$_GET['edit_popup']]);$editPopup=$q->fetch();$tab='popups';}$popups=db()->query('SELECT * FROM popup_campaigns ORDER BY enabled DESC,priority DESC,id DESC LIMIT 200')->fetchAll();$notifs=db()->query('SELECT n.*,u.name target_user_name,(SELECT COUNT(*) FROM notification_reads r WHERE r.notification_id=n.id) read_count FROM site_notifications n LEFT JOIN users u ON u.id=n.target_user_id ORDER BY n.id DESC LIMIT 250')->fetchAll();$users=db()->query("SELECT id,name,role FROM users WHERE status='active' ORDER BY name LIMIT 1000")->fetchAll();$stats=['popups'=>count($popups),'active_popups'=>count(array_filter($popups,fn($p)=>(int)$p['enabled']===1)),'notifications'=>count($notifs),'reads'=>array_sum(array_map(fn($n)=>(int)$n['read_count'],$notifs))];require __DIR__.'/../app/layout.php';page_start('Popups & Notifications',true);
